#!/usr/bin/env node
// Regenerate src/font-data.js from the bundled TTF:
//   npm run embed-font   (node scripts/embed-font.mjs src/font-data.js)
// The font is embedded as base64 so the library keeps working when a bundler
// (such as Astro's) inlines it into a chunk where relative file paths break.
import { readFileSync, writeFileSync } from "node:fs";

const FONT = new URL(
  "../ttf-montserrat/static/Montserrat-Black.ttf",
  import.meta.url,
);
const [output] = process.argv.slice(2);

const base64 = readFileSync(FONT).toString("base64");
writeFileSync(
  output,
  "// Generated by scripts/embed-font.mjs from\n" +
    "// ttf-montserrat/static/Montserrat-Black.ttf (SIL OFL 1.1, see\n" +
    "// ttf-montserrat/OFL.txt). Do not edit by hand.\n" +
    `export default "${base64}";\n`,
);
